// Item icons (lib/item-sprites.mjs, generated by tools/build-item-sprites.mjs from Showdown's items.js spritenum) and the
// teambuilder's item combobox: icon + name per option, type to filter, Up / Down / Enter / Escape, picking writes the draft only.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mech } from './calc-helpers.mjs';
import { bootApp, parseHtml, findAll } from './ui-harness.mjs';
import { device, SET_MINE, flushSaves } from './prep-helpers.mjs';
import { KEYS } from '../lib/prep-schema.mjs';
import { ITEM_SPRITES, iconOffset } from '../lib/item-sprites.mjs';
import { itemIcon } from '../public/prep-ui.js';
import { filterItems, comboStep, itemKey } from '../public/prep-teambuilder.js';

test('the sprite map covers every Champions item, and only those', () => {
  const ids = Object.keys(mech.items);
  assert.deepEqual(ids.filter((i) => !(i in ITEM_SPRITES)), [], 'every item in data/mechanics.json has a Showdown spritenum');
  assert.deepEqual(Object.keys(ITEM_SPRITES).filter((i) => !mech.items[i]), [], 'nothing outside the regulation');
  assert.ok(Object.values(ITEM_SPRITES).every((n) => Number.isInteger(n) && n >= 0));
});

test('icon position on the 16-per-row sheet of 24×24 icons: Life Orb, Sitrus Berry, Charizardite Y', () => {
  assert.deepEqual([ITEM_SPRITES.lifeorb, iconOffset(ITEM_SPRITES.lifeorb)], [249, [216, 360]]);
  assert.deepEqual([ITEM_SPRITES.sitrusberry, iconOffset(ITEM_SPRITES.sitrusberry)], [448, [0, 672]]);
  assert.deepEqual([ITEM_SPRITES.charizarditey, iconOffset(ITEM_SPRITES.charizarditey)], [586, [240, 864]]);
  assert.match(itemIcon('lifeorb'), /class="ii" style="background-position:-216px -360px" aria-hidden="true"/);
  assert.equal(itemIcon(''), '');
});

test('combobox logic: type to filter; Down / Up wrap; Enter picks the active one (or the only match); Escape closes', () => {
  const opts = ['Life Orb', 'Leftovers', 'Sitrus Berry', 'Charizardite Y', "King's Rock"].map((n) => ({ name: itemKey(n), n }));
  assert.deepEqual(filterItems(opts, ' LIFE').map((o) => o.n), ['Life Orb']);
  assert.deepEqual(filterItems(opts, 'berry').map((o) => o.n), ['Sitrus Berry']);
  assert.deepEqual(filterItems(opts, 'sitrusberry').map((o) => o.n), ['Sitrus Berry'], 'spaces ignored');
  assert.deepEqual(filterItems(opts, 'charizardite-y').map((o) => o.n), ['Charizardite Y'], 'hyphens ignored');
  assert.deepEqual(filterItems(opts, 'zzz'), [], 'no match: nothing (the list says "No item matches")');
  assert.equal(filterItems(opts, '').length, 5);
  assert.deepEqual(comboStep(4, -1, 'ArrowDown'), { active: 0, pick: null, close: false });
  assert.deepEqual(comboStep(4, 3, 'ArrowDown').active, 0, 'wraps');
  assert.deepEqual(comboStep(4, 0, 'ArrowUp').active, 3, 'wraps');
  assert.deepEqual(comboStep(4, 2, 'Enter'), { active: 2, pick: 2, close: true });
  assert.deepEqual(comboStep(1, -1, 'Enter').pick, 0, 'the only match');
  assert.deepEqual(comboStep(3, -1, 'Enter').pick, null);
  assert.deepEqual(comboStep(3, 1, 'Escape'), { active: -1, pick: null, close: true });
  assert.equal(comboStep(3, 1, 'a'), null, 'other keys are typing');
});

test('the editor: an accessible item combobox with icons; picking writes the draft only; a wrong stone is refused', async (t) => {
  const storage = device();
  const app = await bootApp({ mode: `prep/my-sets/${SET_MINE}`, storage });
  t.after(() => app.restore());
  await app.waitFor(() => /tb-srow/.test(app.html()), 'the editor', 20000);
  const root = parseHtml(app.html());
  const box = findAll(root, (n) => n.attrs.id === 'tb-item')[0];
  assert.deepEqual([box.attrs.role, box.attrs['aria-controls'], box.attrs['aria-autocomplete'], box.attrs['aria-expanded']], ['combobox', 'tb-itemlist', 'list', 'false']);
  assert.ok(!findAll(root, (n) => n.tag === 'datalist' && n.attrs.id === 'tb-items').length, 'no datalist');
  const list = findAll(root, (n) => n.attrs.id === 'tb-itemlist')[0];
  assert.equal(list.attrs.role, 'listbox');
  const opts = findAll(list, (n) => n.attrs.role === 'option');
  assert.ok(opts.length > 20);
  const lo = opts.find((o) => o.attrs['data-item'] === 'lifeorb');
  assert.ok(findAll(lo, (n) => /\bii\b/.test(n.attrs.class ?? '')).length, 'each option shows its icon');
  assert.ok(opts.some((o) => o.attrs['data-item'] === 'charizarditey') && !opts.some((o) => o.attrs['data-item'] === 'venusaurite'), 'only stones this Pokémon can use');
  assert.match(app.html(), /class="tb-combo-in"><span class="ii"/, 'the chosen item\'s icon sits by the field');
  assert.match(app.html(), /class="tb-nomatch muted" hidden>No item matches</);
  await app.click({ pa: 'tb-item-pick', set: SET_MINE, item: 'lifeorb' });
  await flushSaves(app);
  const lib = JSON.parse(storage.getItem(KEYS.mysets));
  assert.equal(lib.drafts[SET_MINE].data.item, 'lifeorb', 'into the draft');
  assert.equal(lib.sets.find((s) => s.id === SET_MINE).currentV, 1, 'no new version');
  await app.click({ pa: 'tb-item-pick', set: SET_MINE, item: 'venusaurite' });
  assert.match(app.toast.textContent, /isn't an item this Pokémon can hold/);
  // typing a name and leaving the field still works (and is still validated)
  await app.changeData({ pc: 'tb-item', set: SET_MINE }, { value: 'sitrus berry ' });
  await flushSaves(app);
  assert.equal(JSON.parse(storage.getItem(KEYS.mysets)).drafts[SET_MINE].data.item, 'sitrusberry');
});
